        /// Write zeroes to every SubDevice's memory in chunks.
        async fn blank_memory<const LEN: usize>(
            &self,
            start: impl Into<u16>,
        ) -> Result<(), Error> {
            let start = start.into();
            self.pdu_loop
                .pdu_broadcast_zeros(
                    start,
                    LEN as u16,
                    self.timeouts.pdu,
                    self.config.retry_behaviour.retry_count(),
                )
                .await
        }
        async fn reset_subdevices(&self) -> Result<(), Error> {
            {
                {
                    {
                        let lvl = ::log::Level::Debug;
                        if lvl <= ::log::STATIC_MAX_LEVEL && lvl <= ::log::max_level() {
                            ::log::__private_api::log(
                                { ::log::__private_api::GlobalLogger },
                                format_args!("Beginning reset"),
                                lvl,
                                &(
                                    "ethercrab::maindevice",
                                    "ethercrab::maindevice",
                                    ::log::__private_api::loc(),
                                ),
                                (),
                            );
                        }
                    }
                };
            };
            Command::bwr(RegisterAddress::AlControl.into())
                .ignore_wkc()
                .send(self, AlControl::reset())
                .await?;
            for fmmu_idx in 0..16 {
                self.blank_memory::<
                        { Fmmu::PACKED_LEN },
                    >(RegisterAddress::fmmu(fmmu_idx))
                    .await?;
            }
            for sm_idx in 0..16 {
                self.blank_memory::<
                        { SyncManager::PACKED_LEN },
                    >(RegisterAddress::sync_manager(sm_idx))
                    .await?;
            }
            self.blank_memory::<
                    { size_of::<u8>() },
                >(RegisterAddress::DcCyclicUnitControl)
                .await?;
            self.blank_memory::<{ size_of::<u64>() }>(RegisterAddress::DcSystemTime)
                .await?;
            self.blank_memory::<
                    { size_of::<u64>() },
                >(RegisterAddress::DcSystemTimeOffset)
                .await?;
            self.blank_memory::<
                    { size_of::<u32>() },
                >(RegisterAddress::DcSystemTimeTransmissionDelay)
                .await?;
            self.blank_memory::<
                    { size_of::<u32>() },
                >(RegisterAddress::DcSystemTimeDifference)
                .await?;
            self.blank_memory::<{ size_of::<u8>() }>(RegisterAddress::DcSyncActive)
                .await?;
            self.blank_memory::<{ size_of::<u32>() }>(RegisterAddress::DcSyncStartTime)
                .await?;
            self.blank_memory::<{ size_of::<u32>() }>(RegisterAddress::DcSync0CycleTime)
                .await?;
            self.blank_memory::<{ size_of::<u32>() }>(RegisterAddress::DcSync1CycleTime)
                .await?;
            Command::bwr(RegisterAddress::DcControlLoopParam3.into())
                .ignore_wkc()
                .send(self, 0x0c00u16)
                .await?;
            Command::bwr(RegisterAddress::DcControlLoopParam1.into())
                .ignore_wkc()
                .send(self, 0x1000u16)
                .await?;
            {
                {
                    {
                        let lvl = ::log::Level::Debug;
                        if lvl <= ::log::STATIC_MAX_LEVEL && lvl <= ::log::max_level() {
                            ::log::__private_api::log(
                                { ::log::__private_api::GlobalLogger },
                                format_args!("--> Reset complete"),
                                lvl,
                                &(
                                    "ethercrab::maindevice",
                                    "ethercrab::maindevice",
                                    ::log::__private_api::loc(),
                                ),
                                (),
                            );
                        }
                    }
                };
            };
            Ok(())
        }
