        /// Return the current cyclic mailbox counter value, from 0-7.
        ///
        /// Calling this method internally increments the counter, so subequent calls will produce a new
        /// value.
        fn mailbox_counter(&self) -> u8 {
            match self
                .state
                .mailbox_counter
                .fetch_update(
                    Ordering::Release,
                    Ordering::Acquire,
                    |n| { if n >= 7 { Some(1) } else { Some(n + 1) } },
                )
            {
                ::core::result::Result::Ok(t) => t,
                ::core::result::Result::Err(e) => {
                    {
                        ::core::panicking::panic_fmt(
                            format_args!(
                                "unwrap of `{0}` failed: {1:?}",
                                "self.state.mailbox_counter.fetch_update(Ordering::Release, Ordering::Acquire,\n|n| { if n >= 7 { Some(1) } else { Some(n + 1) } })",
                                e,
                            ),
                        );
                    };
                }
            }
        }
        /// Get CoE read/write mailboxes.
        async fn coe_mailboxes(&self) -> Result<(Mailbox, Mailbox), Error> {
            let write_mailbox = self
                .state
                .config
                .mailbox
                .write
                .ok_or(Error::Mailbox(MailboxError::NoReadMailbox))?;
            let read_mailbox = self
                .state
                .config
                .mailbox
                .read
                .ok_or(Error::Mailbox(MailboxError::NoWriteMailbox))?;
            let mailbox_read_sm_status = RegisterAddress::sync_manager_status(
                read_mailbox.sync_manager,
            );
            let mailbox_write_sm_status = RegisterAddress::sync_manager_status(
                write_mailbox.sync_manager,
            );
            for i in 0..10 {
                let sm_status = self
                    .read(mailbox_read_sm_status)
                    .receive::<crate::sync_manager_channel::Status>(self.maindevice)
                    .await?;
                if sm_status.mailbox_full {
                    {
                        {
                            {
                                let lvl = ::log::Level::Debug;
                                if lvl <= ::log::STATIC_MAX_LEVEL
                                    && lvl <= ::log::max_level()
                                {
                                    ::log::__private_api::log(
                                        { ::log::__private_api::GlobalLogger },
                                        format_args!(
                                            "SubDevice {0:#06x} OUT mailbox not empty (status {1:?}). Clearing.",
                                            self.configured_address(),
                                            sm_status,
                                        ),
                                        lvl,
                                        &(
                                            "ethercrab::subdevice",
                                            "ethercrab::subdevice",
                                            ::log::__private_api::loc(),
                                        ),
                                        (),
                                    );
                                }
                            }
                        };
                    };
                    self.read(read_mailbox.address)
                        .ignore_wkc()
                        .receive_slice(self.maindevice, read_mailbox.len)
                        .await?;
                } else {
                    break;
                }
                if i > 0 {
                    self.maindevice.timeouts.loop_tick().await;
                }
                if i > 1 {
                    {
                        {
                            {
                                let lvl = ::log::Level::Debug;
                                if lvl <= ::log::STATIC_MAX_LEVEL
                                    && lvl <= ::log::max_level()
                                {
                                    ::log::__private_api::log(
                                        { ::log::__private_api::GlobalLogger },
                                        format_args!("--> Retrying clear"),
                                        lvl,
                                        &(
                                            "ethercrab::subdevice",
                                            "ethercrab::subdevice",
                                            ::log::__private_api::loc(),
                                        ),
                                        (),
                                    );
                                }
                            }
                        };
                    };
                }
            }
            async {
                loop {
                    let sm_status = self
                        .read(mailbox_write_sm_status)
                        .receive::<crate::sync_manager_channel::Status>(self.maindevice)
                        .await?;
                    if !sm_status.mailbox_full {
                        break Ok(());
                    }
                    self.maindevice.timeouts.loop_tick().await;
                }
            }
                .timeout(self.maindevice.timeouts.mailbox_echo)
                .await
                .inspect_err(|&e| {
                    {
                        {
                            {
                                let lvl = ::log::Level::Error;
                                if lvl <= ::log::STATIC_MAX_LEVEL
                                    && lvl <= ::log::max_level()
                                {
                                    ::log::__private_api::log(
                                        { ::log::__private_api::GlobalLogger },
                                        format_args!(
                                            "Mailbox IN ready error for SubDevice {0:#06x}: {1}",
                                            self.configured_address,
                                            e,
                                        ),
                                        lvl,
                                        &(
                                            "ethercrab::subdevice",
                                            "ethercrab::subdevice",
                                            ::log::__private_api::loc(),
                                        ),
                                        (),
                                    );
                                }
                            }
                        };
                    };
                })?;
            Ok((read_mailbox, write_mailbox))
        }
        /// Wait for a mailbox response
        async fn coe_response(
            &self,
            read_mailbox: &Mailbox,
        ) -> Result<ReceivedPdu, Error> {
            let mailbox_read_sm = RegisterAddress::sync_manager_status(
                read_mailbox.sync_manager,
            );
            async {
                loop {
                    let sm_status = self
                        .read(mailbox_read_sm)
                        .receive::<crate::sync_manager_channel::Status>(self.maindevice)
                        .await?;
                    if sm_status.mailbox_full {
                        break Ok(());
                    }
                    self.maindevice.timeouts.loop_tick().await;
                }
            }
                .timeout(self.maindevice.timeouts.mailbox_echo)
                .await
                .inspect_err(|&e| {
                    {
                        {
                            {
                                let lvl = ::log::Level::Error;
                                if lvl <= ::log::STATIC_MAX_LEVEL
                                    && lvl <= ::log::max_level()
                                {
                                    ::log::__private_api::log(
                                        { ::log::__private_api::GlobalLogger },
                                        format_args!(
                                            "Response mailbox IN error for SubDevice {0:#06x}: {1}",
                                            self.configured_address,
                                            e,
                                        ),
                                        lvl,
                                        &(
                                            "ethercrab::subdevice",
                                            "ethercrab::subdevice",
                                            ::log::__private_api::loc(),
                                        ),
                                        (),
                                    );
                                }
                            }
                        };
                    };
                })?;
            let response = self
                .read(read_mailbox.address)
                .receive_slice(self.maindevice, read_mailbox.len)
                .await?;
            Ok(response)
        }
