        ///
        /// let mut group = group
        ///     .into_pre_op_pdi(&maindevice)
        ///     .await
        ///     .expect("PRE-OP -> PRE-OP with PDI")
        ///     .configure_dc_sync(
        ///         &maindevice,
        ///         DcConfiguration {
        ///             // Start SYNC0 100ms in the future
        ///             start_delay: Duration::from_millis(100),
