        fn ifreq_for(name: &str) -> ifreq {
            let mut ifreq = ifreq {
                ifr_name: [0; libc::IF_NAMESIZE],
                ifr_data: 0,
            };
            for (i, byte) in name.as_bytes().iter().enumerate() {
                ifreq.ifr_name[i] = *byte as libc::c_char;
            }
            ifreq
        }
