    struct ParkSignal {
        current_thread: Thread,
    }
    impl ParkSignal {
        fn new() -> Self {
            Self {
                current_thread: thread::current(),
            }
        }
        fn wait(&self) {
            thread::park();
        }
    }
    impl Wake for ParkSignal {
        fn wake(self: Arc<Self>) {
            self.current_thread.unpark();
        }
    }
